import base, { ignorePatterns } from "@anuragbanerjee/oxc-config/oxfmt";
import { defineConfig } from "oxfmt";

import primitives from "./packages/ui/primitives.json" with { type: "json" };

// shadcn/ui primitives are synced from upstream and never formatted by hand.
const synced = primitives.primitives.map(
  (name) => `packages/ui/src/components/ui/${name}.tsx`,
);

export default defineConfig({
  ...base,
  ignorePatterns: [
    ...ignorePatterns,
    // Generated by `shadcn build`.
    "r",
    // Written by `shadcn add` from the local registry (see scripts/test-fixtures.ts).
    ...synced,
    "fixtures/*/src/components/ui",
    ".changeset/*.md",
    "**/CHANGELOG.md",
  ],
  overrides: [
    {
      // Our own registry sources follow the shadcn house style (no semicolons),
      // like the synced primitives. The CLI only strips `"use client"` for
      // `rsc: false` consumers when the directive has no trailing semicolon.
      // See AGENTS.md.
      files: ["packages/ui/src/**"],
      options: { semi: false },
    },
  ],
  sortTailwindcss: {
    functions: ["cn", "cva", "clsx"],
    stylesheet: "./packages/ui/src/styles/globals.css",
  },
});
